import json
def parse_user_payload(raw):
    try:
        return json.loads(raw), True
    except json.JSONDecodeError as err:
        return {"error": "Invalid JSON", "line": err.lineno}, False

print(parse_user_payload('{"username": "kakade",}'))
print(parse_user_payload('{"username": "Kakade"}'))

def calculate_discount(price, pct):
    if not 0 <= pct <= 100:
        raise ValueError(f"Discount must be 0-100. Got: {pct}")
    return price * (1 - pct / 100)

try:
    calculate_discount(50, 150)
except ValueError as e:
    print(f"Blocked: {e}")

