class InsufficientFundsError(Exception):
    def __init__(self, balance, required):
        super().__init__(f"Balance ${balance} insufficient for ${required}")
        self.balance = balance
        self.required = required

def process_payment(balance, charge):
    if balance < charge:
        raise InsufficientFundsError(balance, charge)
    return balance - charge

try:
    process_payment(20, 100)
except InsufficientFundsError as e:
    print(f"Blocked: {e} shortfall ${e.required - e.balance}")

